function topoSortDFS(adj) {
  const visited = new Set();
  const stack = [];
  function dfs(v) {
    visited.add(v);
    stack.push(v); // BUG: pushed on ENTRY (pre-order)
    for (const w of adj[v]) if (!visited.has(w)) dfs(w);
  }
  for (const v of Object.keys(adj)) if (!visited.has(v)) dfs(v);
  return stack; // BUG: returned without reversing
}
